    {
      "name": "auth"
    },
    {
      "name": "metadata"
    },
    {
      "name": "projects"
    },
    {
      "name": "workflow"
    },
    {
      "name": "transitions"
    },
    {
      "name": "reviews"
    },
    {
      "name": "release"
    },
    {
      "name": "contracts"
    },
